class WishlistScreen extends StatelessWidget {
  static const String routeName = '/wishlist';
  const WishlistScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      extendBodyBehindAppBar: true,
      appBar: AppBar(
        backgroundColor: Colors.transparent,
        elevation: 0,
        leading: Padding(
          padding: const EdgeInsets.all(8.0),
          child: _GlassHeaderButton(
            icon: Icons.arrow_back_ios_new_rounded,
            onTap: () => Navigator.pop(context),
          ),
        ),
        title: Text(
          'WISHLIST',
          style: TextStyle(
            color: GlassTheme.textColor(context),
            fontWeight: FontWeight.w900,
            fontSize: 15,
            letterSpacing: 1.5,
          ),
        ),
        centerTitle: true,
      ),
      body: ZinkoBackground(
        child: SafeArea(
          child: BlocBuilder<WorkspaceBloc, WorkspaceState>(
            builder: (context, state) {
              if (state is WorkspaceLoading) {
                return Center(
                    child: CircularProgressIndicator(
                        color: GlassTheme.textColor(context)));
              }
              if (state is WorkspaceLoaded) {
                final favorites =
                    state.workspaces.where((w) => w.isFavorite).toList();
                if (favorites.isEmpty) return _buildEmptyState(context);
                return ListView.builder(
                  padding: const EdgeInsets.fromLTRB(20, 8, 20, 100),
                  physics: const BouncingScrollPhysics(),
                  itemCount: favorites.length,
                  itemBuilder: (context, index) {
                    final workspace = favorites[index];
                    return GestureDetector(
                      onTap: () => Navigator.pushNamed(
                          context, WorkspaceDetailScreen.routeName,
                          arguments: workspace),
                      child: _WishlistCard(
                        workspace: workspace,
                        onRemove: () {
                          context
                              .read<WorkspaceBloc>()
                              .add(ToggleFavoriteWorkspaceEvent(workspace.id));
                        },
                      )
                          .animate()
                          .fadeIn(delay: (index * 80).ms)
                          ,
                    );
                  },
                );
              }
              if (state is WorkspaceError) {
                return Center(
                    child: Text(state.message,
                        style:
                            TextStyle(color: GlassTheme.textColor(context))));
              }
              return const SizedBox.shrink();
            },
          ),
        ),
      ),
    );
  }

  Widget _buildEmptyState(BuildContext context) {
    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          const Icon(Icons.favorite_rounded,
              size: 56, color: OptimizedColors.white10),
          const SizedBox(height: 12),
          const Text(
            'EMPTY WISHLIST',
            style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w900,
                color: OptimizedColors.white50,
                letterSpacing: 1.5),
          ),
          const SizedBox(height: 6),
          const Text(
            'Your favorite spaces will appear here',
            textAlign: TextAlign.center,
            style: TextStyle(
                fontSize: 13,
                color: OptimizedColors.white50,
                fontWeight: FontWeight.w500),
          ),
          const SizedBox(height: 24),
          GestureDetector(
            onTap: () => Navigator.pop(context),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 14),
              decoration: BoxDecoration(
                color: AppColors.primaryBlue,
                borderRadius: BorderRadius.circular(16),
                boxShadow: [
                  BoxShadow(
                    color: AppColors.primaryBlue.withValues(alpha: 0.3),
                    blurRadius: 15,
                    offset: const Offset(0, 5),
                  )
                ],
              ),
              child: const Text(
                'EXPLORE SPACES',
                style: TextStyle(
                    fontWeight: FontWeight.w900,
                    fontSize: 13,
                    color: AppColors.white,
                    letterSpacing: 0.5),
              ),
            ),
          ).animate().scale(),
        ],
      ),
    );
  }
}

