class EventDetailScreen extends StatefulWidget {
  static const String routeName = '/event-detail';
  final dynamic event;

  const EventDetailScreen({super.key, required this.event});

  @override
  State<EventDetailScreen> createState() => _EventDetailScreenState();
}

class _EventDetailScreenState extends State<EventDetailScreen> {
  late dynamic _event;

  @override
  void initState() {
    super.initState();
    _event = widget.event;
  }

  void _onRegister(BuildContext context) {
    context.read<EventBloc>().add(RegisterEventEvent(_event.id));
  }

  @override
  Widget build(BuildContext context) {
    return BlocConsumer<EventBloc, EventState>(
      listener: (context, state) {
        if (state is EventRegistrationSuccess &&
            state.eventName == _event.title) {
          _showSuccessOverlay(context);
        }
      },
      builder: (context, state) {
        if (state is EventLoaded) {
          try {
            _event = state.events
                .firstWhere((e) => e.id == _event.id, orElse: () => _event);
          } catch (_) {}
        }

        return Scaffold(
            extendBodyBehindAppBar: true,
            body: ZinkoBackground(
              child: Stack(
                children: [
                  CustomScrollView(
                    physics: const BouncingScrollPhysics(),
                    slivers: [
                      _buildSliverAppBar(context),
                      SliverToBoxAdapter(
                        child: Padding(
                          padding: const EdgeInsets.fromLTRB(20, 16, 20, 140),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              _buildGlassHeader(),
                              const SizedBox(height: 12),
                              _buildGlassStatsRow(),
                              const SizedBox(height: 12),
                              _buildGlassDescription(),
                              const SizedBox(height: 12),
                              _buildGlassOrganizer(),
                            ],
                          ),
                        ),
                      ),
                    ],
                  ),
                  Positioned(
                    bottom: 0,
                    left: 0,
                    right: 0,
                    child: _buildActionFAB(context),
